import { test, expect } from '@playwright/test';

test.describe('Notification Message Rendered - Feedback', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notification_message_rendered');
  });

  test('should display notification with success message on click', async ({ page }) => {
    // Verify initial state - no notification visible
    const flashElement = page.getByTestId('flash');
    await expect(flashElement).not.toBeVisible();

    // Locate and click the 'Click here' link using getByRole
    const clickLink = page.getByRole('link', { name: /click here/i });
    await clickLink.click();

    // Verify notification flash element becomes visible
    await expect(flashElement).toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText(/Action successful/i);
    await expect(successMessage).toBeVisible();

    // Verify close icon is present and clickable
    const closeIcon = page.getByRole('button', { name: /close/i });
    await expect(closeIcon).toBeVisible();

    // Verify close icon has correct aria-label
    await expect(closeIcon).toHaveAttribute('aria-label', 'Close notification');

    // Verify notification is dismissed on close
    await closeIcon.click();
    await expect(flashElement).not.toBeVisible();
  });

  test('should display notification with error message on click', async ({ page }) => {
    // Verify initial state - no notification visible
    const flashElement = page.getByTestId('flash');
    await expect(flashElement).not.toBeVisible();

    // Locate and click the 'Click here' link using getByRole
    const clickLink = page.getByRole('link', { name: /click here/i });
    await clickLink.click();

    // Verify notification flash element becomes visible
    await expect(flashElement).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/Action unsuccessful/i);
    await expect(errorMessage).toBeVisible();

    // Verify close icon is present and clickable
    const closeIcon = page.getByRole('button', { name: /close/i });
    await expect(closeIcon).toBeVisible();

    // Verify close icon has correct aria-label
    await expect(closeIcon).toHaveAttribute('aria-label', 'Close notification');

    // Verify notification is dismissed on close
    await closeIcon.click();
    await expect(flashElement).not.toBeVisible();
  });
});
